<?php
$tail=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$tables=[
"CREATE TABLE IF NOT EXISTS hr_schema(version INT PRIMARY KEY)",
"CREATE TABLE IF NOT EXISTS hr_staff(id INT AUTO_INCREMENT PRIMARY KEY,staff_no VARCHAR(20) NULL UNIQUE,user_id INT NULL UNIQUE,status VARCHAR(24) NOT NULL DEFAULT 'draft',version INT NOT NULL DEFAULT 1,data LONGTEXT NOT NULL,exit_at DATE NULL,created_by INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT)",
"CREATE TABLE IF NOT EXISTS hr_catalogue(id INT AUTO_INCREMENT PRIMARY KEY,group_name VARCHAR(20) NOT NULL,name VARCHAR(80) NOT NULL,active TINYINT NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,UNIQUE(group_name,name))",
"CREATE TABLE IF NOT EXISTS hr_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,staff_id INT NOT NULL,actor_id INT NULL,action VARCHAR(80) NOT NULL,reason_html TEXT NOT NULL,details LONGTEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES hr_staff(id) ON DELETE RESTRICT,FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT)",
"CREATE TABLE IF NOT EXISTS hr_leave(id INT AUTO_INCREMENT PRIMARY KEY,staff_id INT NOT NULL,requested_by INT NOT NULL,leave_type VARCHAR(30) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,reason TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by INT NULL,review_reason TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,FOREIGN KEY(staff_id) REFERENCES hr_staff(id) ON DELETE RESTRICT,FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT)",
"CREATE TABLE IF NOT EXISTS hr_items(id INT AUTO_INCREMENT PRIMARY KEY,staff_id INT NOT NULL,name VARCHAR(120) NOT NULL,issued_by INT NOT NULL,issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,returned_by INT NULL,returned_at DATETIME NULL,FOREIGN KEY(staff_id) REFERENCES hr_staff(id) ON DELETE RESTRICT,FOREIGN KEY(issued_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(returned_by) REFERENCES users(id) ON DELETE RESTRICT)",
"CREATE TABLE IF NOT EXISTS hr_operations(actor_id INT NOT NULL,operation_key CHAR(32) NOT NULL,fingerprint CHAR(64) NOT NULL,staff_id INT NOT NULL,PRIMARY KEY(actor_id,operation_key),FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(staff_id) REFERENCES hr_staff(id) ON DELETE RESTRICT)",
"CREATE TABLE IF NOT EXISTS hr_documents(id INT AUTO_INCREMENT PRIMARY KEY,staff_id INT NOT NULL,type_id INT NOT NULL,storage_key CHAR(64) NOT NULL UNIQUE,filename VARCHAR(190) NOT NULL,mime VARCHAR(80) NOT NULL,size_bytes INT NOT NULL,sha256 CHAR(64) NOT NULL,created_by INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES hr_staff(id) ON DELETE RESTRICT,FOREIGN KEY(type_id) REFERENCES hr_catalogue(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT)",
"CREATE TABLE IF NOT EXISTS hr_salary_versions(id INT AUTO_INCREMENT PRIMARY KEY,staff_id INT NOT NULL,preferred VARCHAR(10) NOT NULL,momo_id INT NULL,bank_id INT NULL,effective_date DATE NOT NULL,payload LONGTEXT NOT NULL,reason VARCHAR(500) NOT NULL,created_by INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES hr_staff(id) ON DELETE RESTRICT,FOREIGN KEY(momo_id) REFERENCES hr_catalogue(id) ON DELETE RESTRICT,FOREIGN KEY(bank_id) REFERENCES hr_catalogue(id) ON DELETE RESTRICT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT)"
];
$sql=array_map(static fn($s)=>$s.$tail,$tables);
foreach(['hr_staff','hr_history','hr_leave','hr_items','hr_documents','hr_salary_versions','hr_operations'] as $table)$sql[]="CREATE TRIGGER IF NOT EXISTS {$table}_retain BEFORE DELETE ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HR history is retained'";
foreach(['hr_history','hr_documents','hr_salary_versions','hr_operations'] as $table)$sql[]="CREATE TRIGGER IF NOT EXISTS {$table}_immutable BEFORE UPDATE ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HR history is immutable'";
return $sql;
